1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
7	
8	public class EnsureOwnerTelephoneUnique {
9	
10	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
11	            throws DuplicateTelephoneException {
12	        boolean taken = ownerRepository.findAll().stream()
13	                .anyMatch(other -> other.getTelephone() != null
14	                        && other.getTelephone().equals(owner.getTelephone()));
15	        if (taken) {
16	            throw new DuplicateTelephoneException("Telephone is already used by another owner");
17	        }
18	    }
19	}
