302		protected static int luhn(String s) {
303			int sum = 0;
304			boolean dbl = true;
305			for (int i = s.length() - 1; i >= 0; i--) {
306				char c = s.charAt(i);
307				if (c < '0' || c > '9') {
308					continue;
309				}
310				int d = c - '0';
311				if (dbl) {
312					d *= 2;
313					if (d > 9) {
314						d -= 9;
315					}
316				}
317				sum += d;
318				dbl = !dbl;
319			}
